import { useEffect, useState } from "react";
import "./projectGallery.css";

export default function TwoDDesigns() {
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [zoom, setZoom] = useState(1);

  const closePreview = () => {
    setIsPreviewOpen(false);
    setZoom(1);
  };

  const openPreview = () => {
    setZoom(1);
    setIsPreviewOpen(true);
  };

  useEffect(() => {
    if (!isPreviewOpen) return undefined;

    const closeOnEscape = (event) => {
      if (event.key === "Escape") {
        setIsPreviewOpen(false);
        setZoom(1);
      }
    };

    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [isPreviewOpen]);

  return (
    <main className="project-designs-gallery">
      <button
        type="button"
        className="project-card-2d-button"
        onClick={openPreview}
        aria-label="View 2D design image"
      >
        <img src="/2d_designs.png" alt="2D Designs" className="project-card-2d" />
      </button>

      {isPreviewOpen && (
        <div
          className="image-preview-backdrop"
          onClick={closePreview}
          role="presentation"
        >
          <div
            className="image-preview-dialog"
            role="dialog"
            aria-modal="true"
            aria-label="2D design image preview"
            onClick={(event) => event.stopPropagation()}
          >
            <button
              type="button"
              className="image-preview-close"
              onClick={closePreview}
              aria-label="Close image preview"
            >
              &times;
            </button>
            <div className="image-preview-controls" aria-label="Image zoom controls">
              <button
                type="button"
                onClick={() => setZoom((currentZoom) => Math.min(currentZoom + 0.25, 3))}
                disabled={zoom >= 3}
                aria-label="Zoom in"
              >
                +
              </button>
              <button
                type="button"
                onClick={() => setZoom((currentZoom) => Math.max(currentZoom - 0.25, 1))}
                disabled={zoom <= 1}
                aria-label="Zoom out"
              >
                −
              </button>
            </div>
            <img
              src="/2d_designs.png"
              alt="2D Designs"
              style={{
                width: `${90 * zoom}vw`,
                height: `${90 * zoom}vh`,
              }}
            />
          </div>
        </div>
      )}
    </main>
  );
}
